import{_ as t,o as d,c as o,a3 as s}from"./chunks/framework.D1GAkLkK.js";const u=JSON.parse('{"title":"Exit codes and JSON","description":"","frontmatter":{},"headers":[],"relativePath":"reference/exit-codes-and-json.md","filePath":"reference/exit-codes-and-json.md"}'),i={name:"reference/exit-codes-and-json.md"};function a(c,e,n,r,h,l){return d(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="exit-codes-and-json" tabindex="-1">Exit codes and JSON <a class="header-anchor" href="#exit-codes-and-json" aria-label="Permalink to &quot;Exit codes and JSON&quot;">​</a></h1><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Means</th></tr></thead><tbody><tr><td>0</td><td>Success. Also a command that found nothing to read, such as <code>plan</code> in a project without units, which says so on stderr</td></tr><tr><td>1</td><td>Failure: a unit or task failed, the files are not valid, a unit cannot be planned, or the record of the run could not be written</td></tr><tr><td>2</td><td>Stopped at the plan: changes need approval and no terminal answers, as in CI without <code>--yes</code></td></tr><tr><td>130, 143</td><td>Stopped by SIGINT (Ctrl-C) or SIGTERM</td></tr></tbody></table><ul><li>1 wins over 2: a run where one unit failed and another waits for approval exits with 1.</li><li><code>plan</code> exits with 1 when a unit cannot be planned, and with 0 when a unit is held by another run.</li><li>A run that <code>opstruss runs cancel</code> cancels exits with 1, since it got no signal; <code>runs cancel</code> itself exits with 0 once that run ends as <code>cancelled</code>.</li><li><code>logs -f</code> and <code>runs &lt;id&gt; -f</code> stopped by Ctrl-C exit with 0, since they only read, and so does a daemon stopped by a signal.</li></ul><h2 id="json" tabindex="-1">JSON <a class="header-anchor" href="#json" aria-label="Permalink to &quot;JSON&quot;">​</a></h2><p>With <code>--json</code>, a command that runs something, such as <code>plan</code>, <code>up</code>, <code>destroy</code>, or a task, prints one event per line. A command that reads, such as <code>outputs</code>, <code>list</code>, <code>explain</code>, <code>doctor</code>, <code>runs</code>, and <code>state list</code>, prints one JSON document.</p><p>An event:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;v&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;seq&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;time&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-19T03:21:07.685Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;run&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;20261019T032107Z-4b2e91d0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;log&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;level&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;info&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;address&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;prod/web&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;task&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;up&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;step&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;stream&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stdout&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;added 312 packages&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Is</th></tr></thead><tbody><tr><td><code>v</code></td><td>The version of the shape of events, <code>1</code></td></tr><tr><td><code>seq</code></td><td>The order within the run, since two events can have the same <code>time</code></td></tr><tr><td><code>time</code></td><td>When, in RFC 3339 and UTC</td></tr><tr><td><code>run</code></td><td>The id of the run</td></tr><tr><td><code>type</code></td><td><code>run</code>, <code>plan</code>, <code>approval</code>, <code>unit</code>, <code>task</code>, <code>step</code>, <code>log</code>, or <code>diagnostic</code>; from the daemon also <code>daemon</code>, <code>service</code>, and <code>trigger</code></td></tr><tr><td><code>level</code></td><td><code>debug</code>, <code>info</code>, <code>warn</code>, or <code>error</code></td></tr><tr><td><code>address</code>, <code>task</code>, <code>step</code></td><td>What the event is about, when that applies</td></tr><tr><td><code>stream</code></td><td><code>stdout</code> or <code>stderr</code>, for a line of a program</td></tr><tr><td><code>message</code></td><td>Text for people, with secrets hidden</td></tr><tr><td><code>status</code></td><td><code>running</code> on the first event of a run, a unit operation, a task, or a step, and <code>finished</code> on the last</td></tr><tr><td><code>outcome</code></td><td>On a <code>finished</code> event: <code>success</code>, <code>failure</code>, <code>skipped</code>, or <code>cancelled</code></td></tr><tr><td><code>exit_code</code></td><td>On the last event of a run: the exit code of the command</td></tr><tr><td><code>outputs</code></td><td>On the last event of a run: the outputs of the task</td></tr><tr><td><code>plan</code></td><td>On a <code>plan</code> event: the plan of its unit, as <code>units.&lt;name&gt;.plan</code> reads it</td></tr></tbody></table><ul><li>A reader ignores the fields and types it does not know: a new version may add some, and <code>message</code> is there to show any event.</li><li>The last event of a run is its <code>run</code> event with <code>outcome</code>, <code>exit_code</code>, and <code>outputs</code>, so a script that runs <code>opstruss &lt;task&gt; --json</code> reads the result from one line.</li><li>A unit that is not run, such as one that is unchanged, gets only its last event.</li><li>Secrets and sensitive values are hidden in every event, as they are at the terminal.</li><li>What fails before a run starts, such as a file that is not valid or a stack that the project does not have, is JSON too: a command that prints events prints a <code>diagnostic</code> event for each problem, with its file and line in <code>message</code>, and a last <code>run</code> event with <code>exit_code</code>; a command that prints a document prints <code>{&quot;error&quot;: &quot;&lt;message&gt;&quot;}</code>. stderr has the same as text.</li></ul><p>The record of each run keeps the same events, which <code>opstruss runs &lt;id&gt; --json</code> prints again. In a <code>diagnostic</code> of what fails before a run starts, <code>run</code> is empty, since there is no run.</p><h2 id="documents" tabindex="-1">Documents <a class="header-anchor" href="#documents" aria-label="Permalink to &quot;Documents&quot;">​</a></h2><p>A command that reads prints one JSON object. A later version may add fields to it, never remove one or change what it means. An empty list is <code>[]</code>, never <code>null</code>, and times are RFC 3339 in UTC; those of runs and events are to the millisecond.</p><table tabindex="0"><thead><tr><th>Command</th><th>Fields</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>stack</code>; <code>tasks</code>, each with <code>name</code>, <code>description</code>, <code>internal</code>, <code>triggers</code>, <code>next</code>, and of its last run <code>run</code>, <code>via</code>, <code>outcome</code>, and <code>ended</code>; <code>units</code>, each with <code>address</code>, <code>kind</code>, <code>state</code> (<code>up</code>, <code>pending</code>, <code>absent</code>, or the state of a service), <code>run</code>, and <code>outputs</code>; <code>triggers</code>, with <code>daemon</code> and <code>error</code>, when a task has triggers</td></tr><tr><td><code>runs</code></td><td><code>stack</code>; <code>runs</code>, newest first, each a record of a run (below)</td></tr><tr><td><code>outputs</code></td><td><code>stack</code>; <code>outputs</code>, by name</td></tr><tr><td><code>doctor</code></td><td><code>stack</code>; <code>checks</code>, each with <code>check</code>, <code>status</code>, <code>message</code>, and <code>path</code> or <code>name</code></td></tr><tr><td><code>explain</code></td><td><code>project</code>, <code>stack</code>, <code>inputs</code> (each with its <code>value</code> and where it is <code>from</code>), <code>order</code>, <code>units</code>, <code>tasks</code>, <code>outputs</code></td></tr><tr><td><code>state list</code></td><td><code>stack</code>; <code>records</code>, each with <code>address</code>, <code>id</code>, and <code>kind</code>; <code>kv</code></td></tr><tr><td><code>plugins</code>, <code>plugins fetch</code>, <code>plugins update</code></td><td><code>sources</code></td></tr><tr><td><code>plugins prune</code></td><td><code>removed</code></td></tr><tr><td><code>validate</code></td><td><code>valid</code>, <code>problems</code>, and <code>warnings</code>, each problem and warning with <code>file</code>, <code>line</code>, <code>column</code>, <code>path</code>, and <code>message</code>; only problems make <code>valid</code> false</td></tr><tr><td><code>stop</code></td><td><code>stack</code>, <code>stopped</code></td></tr><tr><td><code>init</code></td><td><code>wrote</code></td></tr><tr><td><code>version</code></td><td><code>version</code>, <code>os</code>, <code>arch</code></td></tr><tr><td>A command that fails before it reads</td><td><code>error</code></td></tr></tbody></table><p>An output, in <code>outputs</code> and in the units of <code>list</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;sensitive&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>value</code> is missing from a sensitive output, unless <code>outputs --show-sensitive</code> shows it.</li><li><code>type</code> is the type that the unit or its plugin declares, when it does.</li></ul><p>A record of a run has <code>version</code>; <code>opstruss</code>, the version of OpsTruss that ran it; <code>run</code>; <code>parent</code>, the run it ran inside; <code>project</code>, <code>stack</code>, <code>command</code>, <code>task</code>, and <code>args</code>; <code>trigger</code>, what made it, and <code>simulated</code> for <code>--event</code>; <code>user</code>, <code>host</code>, <code>hostname</code>, and <code>pid</code>; <code>started</code> and <code>ended</code>; <code>status</code>, <code>outcome</code>, <code>reason</code> (why it ended <code>cancelled</code>), and <code>exit_code</code>; <code>units</code> and <code>tasks</code>, what ran inside it; <code>outputs</code>; <code>events_incomplete</code> when its events could not all be written; <code>no_deps</code>; <code>rerun_of</code>; and <code>replay</code>, what <code>runs rerun</code> needs.</p><h2 id="color" tabindex="-1">Color <a class="header-anchor" href="#color" aria-label="Permalink to &quot;Color&quot;">​</a></h2><p><code>NO_COLOR</code> that is not empty turns color off; <code>FORCE_COLOR</code> or <code>CLICOLOR_FORCE</code> that is not empty or <code>0</code> turns it on; <code>TERM=dumb</code> turns it off; otherwise there is color at a terminal and in GitHub Actions. stdout and stderr are decided apart. With <code>--json</code>, only <code>FORCE_COLOR</code> and <code>CLICOLOR_FORCE</code> turn it on.</p>',20)])])}const k=t(i,[["render",a]]);export{u as __pageData,k as default};
